SERVICE_BY_OP: dict[str, Service] = {s.op: s for s in SERVICES}
_ALIAS: list[tuple[re.Pattern[str], Service]] = [(_pattern(a), s) for s in SERVICES for a in s.aliases]


def match_service(name: str) -> tuple[Service, dict[str, str]] | None:
    """Resolve a WS service name (uav/{id}/cmd/goto, fleet/cmd/rtl, sim/play ...) to its Service and path parameters."""
    for s in SERVICES:
        m = s.pattern.match(name)
        if m:
            return s, m.groupdict()
    for p, s in _ALIAS:
        m = p.match(name)
        if m:
            return s, m.groupdict()
    return None


def admission_column(fs: int, flags: int) -> int:
    """Column index of the admission matrix: RTL and LANDING split by flags.FAILSAFE (operator vs automatic)."""
    auto = bool(flags & FlightFlags.FAILSAFE)
    order = [FlightState.UNKNOWN, FlightState.DISARMED, FlightState.PREFLIGHT, FlightState.READY, FlightState.TAKING_OFF,
             FlightState.FLYING, FlightState.CORRECTING, FlightState.HOLD]
    if fs in order:
        return order.index(fs)
    if fs == FlightState.RTL:
        return 9 if auto else 8
    if fs == FlightState.LANDING:
        return 11 if auto else 10
    return {FlightState.ELAND: 12, FlightState.FAILSAFE: 13, FlightState.LANDED: 14, FlightState.CRASHED: 15}[FlightState(fs)]


def admit_symbol(op: str, fs: int, flags: int) -> tuple[str, str | None]:
    """(symbol, condition id) for a vehicle command; symbol Y, =, S, - (AWR-12 §5.2). Conditions are applied by the caller."""
    s = SERVICE_BY_OP[op]
    if s.admission is None:
        raise KeyError(f"{op} has no admission row")
    col = admission_column(fs, flags)
    return s.admission[col], s.admission_cond.get(ADMISSION_COLUMNS[col])
